/* ===================== BÀI 11 · CODE, XDATA, MOVC và MOVX ===================== */
/* Bài 11 · CODE, XDATA, MOVC và MOVX (AMTS-EMB-001-M03-L03, MC51-011) — sinh bởi tools/author/mcu8051/l11.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR11=[{"label":"Ví dụ: Bảng mã LED 7 đoạn trong CODE","code":"; Ví dụ 1: tra mã LED 7 đoạn anode chung từ bảng CODE\n; Đoạn a..g, dp ở P0.0..P0.7 (sáng khi bit = 0).\n        ORG     0000H\n        MOV     A,#5                    ; chữ số cần hiện\n        MOV     DPTR,#MA7D\n        MOVC    A,@A+DPTR               ; A = mã của chữ số 5\n        MOV     P0,A                    ; xuất các đoạn\n        MOV     P2,#0FEH                ; P2.0 = 0: bật chữ số 1\n        SJMP    $\nMA7D:   DB      0C0H,0F9H,0A4H,0B0H,99H ; 0..4\n        DB      92H,82H,0F8H,80H,90H    ; 5..9\n        END\n","note":"MOVC lấy mã của chữ số 5 (92H) từ bảng; ghi ra P0 làm sáng các đoạn a, c, d, f, g; P2.0 = 0 chọn chữ số đầu tiên. Đoán trước: muốn hiện số 7 thì đổi A thành bao nhiêu và P0 nhận mã gì? (A = 7, P0 = F8H.)","dev":{"seg":true},"fosc":12000000},{"label":"Ví dụ: MOVC A,@A+PC đọc bảng ngay sau code","code":"; Ví dụ 2: MOVC A,@A+PC, bảng đặt ngay sau đoạn code\n; PC lúc đọc bảng = địa chỉ của lệnh SAU MOVC.\n        ORG     0000H\n        MOV     A,#6                    ; chỉ số 6\n        ADD     A,#4                    ; bù 4 byte: MOV 30H,A + SJMP $\n        MOVC    A,@A+PC                 ; đọc ô (PC + A)\n        MOV     30H,A\n        SJMP    $\nBINHP:  DB      0,1,4,9,16,25,36,49\n        END\n","note":"MOVC nằm ở 0004H nên PC lúc đọc là 0005H. Giữa 0005H và bảng (0009H) có 4 byte, vì thế ADD A,#4: A = 6 + 4 = 10, đọc ô 0005H + 10 = 000FH, là byte chỉ số 6 của bảng (đếm từ 0): 36 = 24H.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Quên bù độ lệch của MOVC @A+PC","code":"; Ví dụ 3: như ví dụ 2 nhưng quên ADD A,#4\n; Chip: AT89S52.\n        ORG     0000H\n        MOV     A,#6                    ; chỉ số 6\n        MOVC    A,@A+PC                 ; đọc ô 0003H + 6 = 0009H\n        MOV     30H,A\n        SJMP    $\nBINHP:  DB      0,1,4,9,16,25,36,49\n        END\n","note":"Thiếu ADD A,#4: MOVC đọc ô 0003H + 6 = 0009H, rơi vào byte chỉ số 2 của bảng (byte thứ ba, đếm từ 0) nên A = 04H thay vì 24H. Không có lỗi nào được báo; chỉ thấy khi so kết quả.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Ghi rồi đọc RAM ngoài qua DPTR","code":"; Ví dụ 4: RAM ngoài (XDATA) chỉ đọc ghi bằng MOVX\n; Giả định: bo có RAM ngoài ở 0000H-7FFFH.\n        ORG     0000H\n        MOV     DPTR,#0010H             ; địa chỉ XDATA 0010H\n        MOV     A,#5AH\n        MOVX    @DPTR,A                 ; XDATA 0010H = 5AH\n        INC     DPTR\n        MOV     A,#0A5H\n        MOVX    @DPTR,A                 ; XDATA 0011H = A5H\n        MOV     DPTR,#0010H\n        MOVX    A,@DPTR                 ; đọc lại: A = 5AH\n        MOV     30H,A\n        SJMP    $\n        END\n","note":"Gõ 0000 vào ô Từ địa chỉ của khu RAM ngoài: ô 0010H = 5AH, 0011H = A5H. Ô RAM trong 10H, 11H vẫn 00H: cùng con số nhưng là hai bộ nhớ khác nhau. Mỗi MOVX và INC DPTR tốn 2 chu kỳ; tổng 15 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: MOVX @R0 và trang trong P2","code":"; Ví dụ 5: MOVX @R0: byte thấp từ R0, byte cao từ P2\n; Giả định: bo có RAM ngoài ở 0000H-7FFFH.\n        ORG     0000H\n        MOV     P2,#00H                 ; trang 00H\n        MOV     R0,#20H\n        MOV     A,#11H\n        MOVX    @R0,A                   ; XDATA 0020H = 11H\n        MOV     P2,#01H                 ; trang 01H\n        MOV     A,#22H\n        MOVX    @R0,A                   ; XDATA 0120H = 22H\n        MOV     P2,#00H\n        MOVX    A,@R0                   ; đọc lại XDATA 0020H\n        SJMP    $\n        END\n","note":"Cùng R0 = 20H, lần ghi thứ hai đi tới 0120H vì P2 = 01H. Gõ 0100 vào ô Từ địa chỉ để thấy ô 0120H = 22H. Lệnh cuối đọc lại 0020H (P2 = 00H) nên A = 11H.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: MOV không đọc được RAM ngoài","code":"; Ví dụ 6: dùng MOV để đọc RAM ngoài\n; Chip: AT89S52.\n        ORG     0000H\n        MOV     DPTR,#0010H\n        MOV     A,@DPTR                 ; ý định: đọc XDATA 0010H\n        SJMP    $\n        END\n","note":"Bấm Chạy: trình dịch báo lỗi ở dòng 5. MOV chỉ làm việc với RAM trong và SFR; RAM ngoài chỉ đi qua MOVX A,@DPTR.","dev":{"led":true},"fosc":12000000}];
