makeQuiz("quiz11","score11",[{"q": "Sau MOV DPTR,#0100H, MOV A,#2 và MOVC A,@A+DPTR, A nhận byte nào?", "o": ["Byte ở địa chỉ 0102H của RAM ngoài", "Byte ở địa chỉ 0102H của bộ nhớ chương trình", "Byte ở ô 02H của RAM trong", "Byte ở địa chỉ 0100H của bộ nhớ chương trình"], "a": 1, "e": "MOVC luôn đọc CODE, tại DPTR + A = 0100H + 2. RAM ngoài chỉ được đọc bằng MOVX; lựa chọn cuối quên cộng chỉ số A."}, {"q": "Dòng nào làm trình dịch báo lỗi?", "o": ["MOVX A,@DPTR", "MOV A,@DPTR", "MOVC A,@A+PC", "MOVX @R1,A"], "a": 1, "e": "Đọc qua @DPTR là truy cập RAM ngoài nên phải dùng MOVX. Ba dòng còn lại là lệnh hợp lệ của 8051."}, {"q": "P2 đang chứa 12H và R1 = 34H. Lệnh MOVX A,@R1 đọc địa chỉ XDATA nào?", "o": ["0034H", "3412H", "0012H", "1234H"], "a": 3, "e": "Với MOVX @Ri, byte thấp địa chỉ là R1, byte cao là nội dung chốt P2 xuất ra chân: 12H:34H. 0034H là kết quả khi quên rằng P2 vẫn đưa byte cao ra bus."}, {"q": "Lệnh MOVC A,@A+PC nằm ở địa chỉ 0002H, trước đó A = 06H. Lệnh đọc byte ở địa chỉ CODE nào?", "o": ["0009H", "0008H", "0006H", "000AH"], "a": 0, "e": "MOVC A,@A+PC dài 1 byte nên lúc đọc PC = 0003H (địa chỉ lệnh sau). 0003H + 6 = 0009H. 0008H là kết quả khi lấy địa chỉ của chính lệnh MOVC."}, {"q": "Bo AT89S52 gắn chip RAM ngoài 32 KB làm XDATA, truy cập bằng MOVX @DPTR. Nhóm chân nào không còn dùng làm cổng vào/ra tự do?", "o": ["Chỉ P0", "P1 và P3.0, P3.1", "P0, P2 và P3.6, P3.7", "Không chân nào, MOVX dùng bus riêng"], "a": 2, "e": "P0 dồn kênh byte thấp địa chỉ và dữ liệu, P2 xuất byte cao địa chỉ, P3.6 và P3.7 là WR và RD. P1 không tham gia bus ngoài."}]);

